    if not cwd.startswith('/') or cwd == '':
        return None

    # Normalize cwd to remove trailing slashes (except for root)
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative, otherwise use path
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'

    # Split the path into components
    if path.startswith('/'):
        components = path[1:].split('/')
    else:
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
