        if candidate in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[candidate]

            # Resolve relative symlink target
            if not target.startswith('/'):
                # Relative to the directory containing the link
                if candidate == '/':
                    target_base = '/'
                else:
                    target_base = candidate.rsplit('/', 1)[0]
                    if target_base == '':
                        target_base = '/'

                if target_base == '/':
                    target = '/' + target
                else:
                    target = target_base + '/' + target

            # Parse the target and insert its components at the current position
            if target.startswith('/'):
                target_components = target[1:].split('/')
            else:
                target_components = target.split('/')

            # Replace current with the start of target resolution
            current = '/'
            # Insert target components at position i, replacing current component
            components = target_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just update current
        current = candidate
        i += 1

    # Ensure result has no trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

